    {
      "category": "sequence_modeling",
      "rationale": "Halve the starting causal context length using max(1, ceil(L/2)) across all four datasets to reduce stale-history dilution. Existing sampling and validation retain recent interactions chronologically; checkpoint metadata and the predictor writer already propagate MAXLEN consistently. Preserve all other model and training settings.",
      "edits": [
        {
          "find": "MAXLEN       = int(os.environ.get(\"SASREC_MAXLEN\",    \"128\"))",
          "replace": "MAXLEN       = max(1, (int(os.environ.get(\"SASREC_MAXLEN\", \"128\")) + 1) // 2)"
        }
      ]
    }
  ],
  "change_summary": "Reduce causal history length from 128 to 64 by default, with matching training, validation, positional embedding size, checkpoint metadata, and prediction context."
}
